code.java:
class Solution {
    public int countDigitOne(int n){
        long answer=0;
        for(long factor=1;factor<=n;factor*=10){
            long high=n/(factor*10),current=n/factor%10,low=n%factor;
            answer+=high*factor;
            if(current==1)answer+=low+1;
            else if(current>1)answer+=factor;
        }
        return(int)answer;
    }
}

code.kotlin:
class Solution {
    fun countDigitOne(n:Int):Int{
        var answer=0L;
        var factor=1L;
        while(factor<=n){
            val high=n/(factor*10);
            val current=n/factor%10;
            val low=n%factor;
            answer+=high*factor;
            if(current==1L)answer+=low+1 else if(current>1L)answer+=factor;
            factor*=10
        };
        return answer.toInt()
    }
}

